#!/usr/bin/env python3
"""
Script to reproduce the GW190521 event_gps issue.

The issue: event_gps('GW190521') fails because it matches multiple events 
including 'GW190521_074359' due to substring matching.
"""

from gwosc import datasets

def test_original_issue():
    """Test the original issue reported"""
    print("Testing original issue...")
    try:
        t0 = datasets.event_gps('GW190521')
        print(f"SUCCESS: Got GPS time for GW190521: {t0}")
        return True
    except ValueError as e:
        print(f"FAILED: {e}")
        return False

def test_exact_matching():
    """Test that exact matching works properly"""
    print("\nTesting exact matching behavior...")

    # These should work (exact matches)
    test_events = [
        'GW170817',  # known good event
        'GW150914',  # another known good event
    ]

    for event in test_events:
        try:
            gps = datasets.event_gps(event)
            print(f"SUCCESS: {event} -> {gps}")
        except Exception as e:
            print(f"FAILED: {event} -> {e}")

if __name__ == "__main__":
    success = test_original_issue()
    test_exact_matching()

    if not success:
        print("\nIssue reproduced successfully!")
        exit(1)
    else:
        print("\nIssue appears to be fixed!")
        exit(0)

