def _fetch_allevents_event_json(
        event,
        catalog=None,
        version=None,
        full=False,
        host=DEFAULT_URL,
):
    """Returns the JSON metadata from the allevents view for a specific event

    The raw JSON data are packaged to look the same as if they came from
    a full event API query, i.e. nested under `'events`'.
    """
    allevents = fetch_allevents_json(full=full, host=host)["events"]

    def _match(keyvalue, exact_only=False):
        dset, metadata = keyvalue
        match_options = {
            dset,
            metadata["commonName"],  # full name
        }
        if not exact_only:
            match_options.add(metadata["commonName"].split("_", 1)[0])  # GWYYMMDD prefix

        if event not in match_options:
            return
        if version is not None and metadata["version"] != version:
            return
        if catalog is not None and metadata["catalog.shortName"] != catalog:
            return
        return True

    # First try exact matches only
    exact_matched = list(filter(lambda kv: _match(kv, exact_only=True), allevents.items()))
    names_exact = set(x[1]["commonName"] for x in exact_matched)

    # If we have exactly one exact match, return it
    if len(exact_matched) == 1:
        key, meta = sorted(exact_matched, key=lambda x: x[1]["version"])[-1]
        return {"events": {key: meta}}

    # If we have multiple exact matches, this is still ambiguous
    if len(exact_matched) > 1:
        raise ValueError(
            "multiple events matched for {!r}: '{}'".format(
                event,
                "', '".join(names_exact),
            ),
        )

    # If no exact matches, fall back to the original behavior (including prefix matches)
    matched = list(filter(_match, allevents.items()))

