#!/usr/bin/env python3
"""
Test that the hostname fix works across all JSON schema draft versions.
"""

import fastjsonschema

def test_all_drafts():
    """Test hostname validation across different drafts"""

    # Test schemas for different drafts
    schemas = [
        {
            "$schema": "http://json-schema.org/draft-04/schema#",
            "type": "object",
            "properties": {
                "host": {"type": "string", "format": "hostname"}
            }
        },
        {
            "$schema": "http://json-schema.org/draft-06/schema#",
            "type": "object",
            "properties": {
                "host": {"type": "string", "format": "hostname"}
            }
        },
        {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
                "host": {"type": "string", "format": "hostname"}
            }
        }
    ]

    test_hosts = ["example.de", "test.co.uk", "google.com", "a.b"]

    for i, schema in enumerate(schemas):
        draft_version = schema["$schema"].split("/")[-2]
        print(f"\nTesting {draft_version}:")
        print("-" * 30)

        validate = fastjsonschema.compile(schema)

        for host in test_hosts:
            try:
                result = validate({"host": host})
                print(f"✓ '{host}' -> SUCCESS")
            except Exception as e:
                print(f"✗ '{host}' -> FAILED: {e}")

if __name__ == "__main__":
    test_all_drafts()

