def fix_nsmap(nsmap):
    """Fix namespace map by replacing None keys with a valid prefix.

    lxml's XPath evaluator doesn't support None as namespace prefix,
    so we replace it with 'default' to avoid "TypeError: empty namespace 
    prefix is not supported in XPath".

    Args:
        nsmap (dict): Namespace map that may contain None as a key

    Returns:
        dict: Fixed namespace map with valid prefixes
    """
    if not nsmap:
        return {}

    # Make a copy to avoid modifying the original
    fixed_nsmap = {}
    for prefix, uri in nsmap.items():
        if prefix is None:
            # Use 'default' as prefix for default namespace
            # Check if 'default' is already taken, if so, use a unique variant
            default_prefix = 'default'
            counter = 1
            while default_prefix in nsmap or default_prefix in fixed_nsmap:
                default_prefix = f'default{counter}'
                counter += 1
            fixed_nsmap[default_prefix] = uri
        else:
            fixed_nsmap[prefix] = uri

    return fixed_nsmap

