def components(arg):
    """Converts a dict of components to the format expected by the Google Maps
    server.

    For example:
    c = {"country": "US", "postal_code": "94043"}
    convert.components(c)
    # 'country:US|postal_code:94043'

    Multiple values for the same component type are also supported:
    c = {"locality": ["New York", "Brooklyn"]}
    convert.components(c)
    # 'locality:New York|locality:Brooklyn'

    :param arg: The component filter.
    :type arg: dict

    :rtype: basestring
    """
    if isinstance(arg, dict):
        components_list = []
        for key, value in arg.items():
            if _is_list(value):
                # Handle list of values for the same component type
                for item in value:
                    components_list.append("%s:%s" % (key, item))
            else:
                # Handle single value
                components_list.append("%s:%s" % (key, value))
        return "|".join(sorted(components_list))

    raise TypeError(
        "Expected a dict for components, "
        "but got %s" % type(arg).__name__)

