def beforeSummaryReport(self, event):
    """Output profiling results"""
    # write prof output to stream
    class Stream:

        def write(self, *msg):
            for m in msg:
                event.stream.write(m)
                event.stream.write(' ')
            event.stream.flush()
    stream = Stream()

    # Dump stats to file first, then load with pstats
    self.prof.dump_stats(self.pfile)
    prof_stats = pstats.Stats(self.pfile)
    prof_stats.sort_stats(self.sort)
    event.stream.writeln(util.ln("Profiling results"))
    tmp = prof_stats.stream
    prof_stats.stream = stream
    try:
        if self.restrict:
            prof_stats.print_stats(*self.restrict)
        else:
            prof_stats.print_stats()
    finally:
        prof_stats.stream = tmp
    event.stream.writeln('')

    if self.clean:
        if self.fileno:
            try:
                os.close(self.fileno)
            except OSError:
                pass
        try:
            os.unlink(self.pfile)
        except OSError:
            pass

