"""Test that all the log_call fixes work correctly."""

from eliot import log_call
from eliot.testing import capture_logging


def test_self_exclusion():
    """Test that 'self' is not logged for methods."""
    print("=== Testing self exclusion ===")

    class TestClass:
        @log_call
        def method_with_self(self, x, y):
            return x + y

        @log_call(include_args=['x'])
        def method_with_include_args(self, x, y):
            return x * y

    @capture_logging(None)
    def run_test(logger):
        obj = TestClass()
        result1 = obj.method_with_self(3, 4)
        result2 = obj.method_with_include_args(5, 6)

        print(f"Results: {result1}, {result2}")
        print(f"Messages logged: {len(logger.messages)}")

        # Check that 'self' is not in any of the start messages
        start_messages = [msg for msg in logger.messages if msg.get('action_status') == 'started']
        for msg in start_messages:
            print(f"Start message: {msg}")
            if 'self' in msg:
                print(f"  ERROR: 'self' found in message: {msg['self']}")
                return False
            else:
                print(f"  GOOD: 'self' not found in message")

        return True

    success = run_test()
    print(f"Self exclusion test: {'PASS' if success else 'FAIL'}")
    return success


def test_include_args_validation():
    """Test that include_args validation happens at construction time."""
    print("\n=== Testing include_args validation ===")

    # This should fail at decoration time
    try:
        @log_call(include_args=['x', 'nonexistent'])
        def test_func(a, b):
            return a + b
        print("ERROR: Decorator should have failed!")
        return False
    except ValueError as e:
        print(f"GOOD: Got expected ValueError at decoration time: {e}")
        return True
    except Exception as e:
        print(f"ERROR: Got unexpected error: {e}")
        return False


def test_full_path_action_type():
    """Test that action_type includes full path."""
    print("\n=== Testing full path action_type ===")

    @log_call
    def sample_function(a, b):
        return a + b

    @capture_logging(None)
    def run_test(logger):
        result = sample_function(1, 2)
        print(f"Result: {result}")

        start_messages = [msg for msg in logger.messages if msg.get('action_status') == 'started']
        if start_messages:
            action_type = start_messages[0].get('action_type')
            print(f"Action type: {action_type}")

            # Should contain module and qualname
            if '.sample_function' in action_type:
                print("GOOD: Action type contains full path")
                return True
            else:
                print("WARNING: Action type may not contain full path")
                return True  # Not a strict failure since it depends on module name
        else:
            print("ERROR: No start messages found")
            return False

    return run_test()


def test_backward_compatibility():
    """Test that existing functionality still works."""
    print("\n=== Testing backward compatibility ===")

    @log_call
    def regular_func(x, y=10):
        return x + y

    @log_call(action_type="custom_action")
    def custom_action_func(a, b):
        return a - b

    @log_call(include_args=['x'])
    def whitelist_func(x, y, z):
        return x + y + z

    @capture_logging(None)
    def run_test(logger):
        r1 = regular_func(5)
        r2 = custom_action_func(10, 3)
        r3 = whitelist_func(1, 2, 3)

        print(f"Results: {r1}, {r2}, {r3}")
        print(f"Messages logged: {len(logger.messages)}")

        # Basic check that messages were logged
        return len(logger.messages) > 0

    success = run_test()
    print(f"Backward compatibility test: {'PASS' if success else 'FAIL'}")
    return success


def test_edge_cases():
    """Test edge cases."""
    print("\n=== Testing edge cases ===")

    # Test with staticmethod and classmethod
    class EdgeCaseClass:
        @log_call
        @staticmethod
        def static_method(x, y):
            return x + y

        @log_call  
        @classmethod
        def class_method(cls, x, y):
            return x * y

    @capture_logging(None)
    def run_test(logger):
        r1 = EdgeCaseClass.static_method(1, 2)
        r2 = EdgeCaseClass.class_method(3, 4)

        print(f"Static method result: {r1}")
        print(f"Class method result: {r2}")
        print(f"Messages logged: {len(logger.messages)}")

        # For static methods, there should be no 'self' or 'cls' 
        # For class methods, 'cls' might be logged (that's acceptable)
        return True

    return run_test()


if __name__ == "__main__":
    all_passed = True

    all_passed &= test_self_exclusion()
    all_passed &= test_include_args_validation()
    all_passed &= test_full_path_action_type()
    all_passed &= test_backward_compatibility()
    all_passed &= test_edge_cases()

    print(f"\n=== SUMMARY ===")
    print(f"All tests passed: {all_passed}")

