def log_call(
        wrapped_function=None, action_type=None, include_args=None,
        include_result=True
):
    """Decorator/decorator factory that logs inputs and the return result.

    If used with inputs (i.e. as a decorator factory), it accepts the following
    parameters:

    @param action_type: The action type to use.  If not given the function name
        will be used.
    @param include_args: If given, should be a list of strings, the arguments to log.
    @param include_result: True by default. If False, the return result isn't logged.
    """
    if wrapped_function is None:
        return partial(log_call, action_type=action_type, include_args=include_args,
                       include_result=include_result)

    # Handle special descriptors like staticmethod and classmethod
    # These need to be unwrapped to get to the actual function
    original_function = wrapped_function
    while hasattr(wrapped_function, '__func__'):
        wrapped_function = wrapped_function.__func__

    # Validate include_args at construction time:
    if include_args is not None:
        # Get function signature to validate arguments exist
        try:
            # Use inspect.signature if available (Python 3.3+), otherwise fall back to getcallargs
            import inspect
            if hasattr(inspect, 'signature'):
                sig = inspect.signature(wrapped_function)
                valid_args = set(sig.parameters.keys())
            else:
                # Fallback for older Python versions - skip validation to avoid breaking things
                valid_args = None
        except Exception:
            # If we can't validate, let it fail at runtime as before
            valid_args = None

        if valid_args is not None:
            include_args_set = set(include_args)
            invalid_args = include_args_set - valid_args
            if invalid_args:
                raise ValueError(
                    "include_args contains arguments that don't exist in function signature: {}".format(
                        sorted(invalid_args)))

    # Generate better action_type with full path on Python 3:
    if action_type is None:
        if (hasattr(wrapped_function, '__qualname__') and hasattr(wrapped_function, '__module__') and
            wrapped_function.__module__ is not None):
            # Python 3: use module + qualified name for better identification
            action_type = '{}.{}'.format(wrapped_function.__module__, wrapped_function.__qualname__)
        else:
            # Fallback to function name
            action_type = wrapped_function.__name__

    @wraps(original_function)
    def logging_wrapper(*args, **kwargs):
        callargs = getcallargs(wrapped_function, *args, **kwargs)

        # Don't log 'self' parameter for methods:
        if ('self' in callargs and len(args) > 0 and args[0] is not None and 
            hasattr(args[0], '__class__')):
            # This looks like a method call, remove 'self'
            callargs = {k: v for k, v in callargs.items() if k != 'self'}

        # Filter arguments to log, if necessary:
        if include_args is not None:
            callargs = {k: callargs[k] for k in include_args}

        with start_action(action_type=action_type, **callargs) as ctx:
            result = original_function(*args, **kwargs)
            if include_result:
                ctx.add_success_fields(result=result)
            return result

    return logging_wrapper

