"""Test self exclusion feature."""

from eliot import log_call, start_action, Message
from eliot._output import MemoryLogger
from eliot import add_destinations, remove_destination


def test_self_exclusion():
    """Test that self is not logged in method calls."""
    print("Testing self exclusion...")

    class TestClass:
        @log_call
        def method(self, x, y):
            return x + y

        @log_call(include_args=['x'])
        def method_with_whitelist(self, x, y):
            return x * y

    # Set up logging
    logger = MemoryLogger()
    add_destinations(logger)

    try:
        obj = TestClass()

        # Call methods
        result1 = obj.method(3, 4)
        result2 = obj.method_with_whitelist(5, 6)

        print(f"Results: {result1}, {result2}")
        print(f"Messages logged: {len(logger.messages)}")

