#!/usr/bin/env python3
"""
Comprehensive test script for the nested metadata fix.
"""

from dataclasses_avroschema import AvroModel
from dataclasses import dataclass
import typing

# Test 1: Original issue - basic nested with schema_name
@dataclass
class MyClass1(AvroModel):
    field_1: str
    class Meta:
        schema_name = "custom_class"

@dataclass 
class MySecondClass1(AvroModel):
    field_2: MyClass1
    class Meta:
        schema_name = "custom_name"

# Test 2: Nested without schema_name (should use class name)
@dataclass
class MyClass2(AvroModel):
    field_1: str

@dataclass 
class MySecondClass2(AvroModel):
    field_2: MyClass2
    class Meta:
        schema_name = "custom_name2"

# Test 3: Deeply nested
@dataclass
class Level3Class(AvroModel):
    field_3: str
    class Meta:
        schema_name = "level_three"

@dataclass
class Level2Class(AvroModel):
    field_2: Level3Class
    class Meta:
        schema_name = "level_two"

@dataclass
class Level1Class(AvroModel):
    field_1: Level2Class
    class Meta:
        schema_name = "level_one"

# Test 4: Multiple nested fields with different schema names
@dataclass
class ClassA(AvroModel):
    value: str
    class Meta:
        schema_name = "schema_a"

@dataclass
class ClassB(AvroModel):
    value: int
    class Meta:
        schema_name = "schema_b"

@dataclass
class ContainerClass(AvroModel):
    field_a: ClassA
    field_b: ClassB
    regular_field: str
    class Meta:
        schema_name = "container"

# Test 5: List of nested objects
@dataclass
class ListItem(AvroModel):
    item_value: str
    class Meta:
        schema_name = "list_item_schema"

@dataclass
class ListContainer(AvroModel):
    items: typing.List[ListItem]
    class Meta:
        schema_name = "list_container"

def test_case_1_basic_nested():
    """Test basic nested with schema_name."""
    result = MySecondClass1.avro_schema_to_python()
    nested_name = result['fields'][0]['type']['name']
    assert nested_name == "custom_class", f"Expected 'custom_class', got '{nested_name}'"
    print("✅ Test 1 passed: Basic nested with schema_name")

def test_case_2_no_schema_name():
    """Test nested without schema_name (should use class name)."""
    result = MySecondClass2.avro_schema_to_python()
    nested_name = result['fields'][0]['type']['name']
    assert nested_name == "MyClass2", f"Expected 'MyClass2', got '{nested_name}'"
    print("✅ Test 2 passed: Nested without schema_name uses class name")

def test_case_3_deeply_nested():
    """Test deeply nested structures."""
    result = Level1Class.avro_schema_to_python()
    level2 = result['fields'][0]['type']
    level3 = level2['fields'][0]['type']

    assert result['name'] == "level_one", f"Level 1 name wrong: {result['name']}"
    assert level2['name'] == "level_two", f"Level 2 name wrong: {level2['name']}"
    assert level3['name'] == "level_three", f"Level 3 name wrong: {level3['name']}"
    print("✅ Test 3 passed: Deeply nested structures")

def test_case_4_multiple_nested():
    """Test multiple nested fields with different schema names."""
    result = ContainerClass.avro_schema_to_python()

    field_a_type = result['fields'][0]['type']
    field_b_type = result['fields'][1]['type']

    assert field_a_type['name'] == "schema_a", f"Field A name wrong: {field_a_type['name']}"
    assert field_b_type['name'] == "schema_b", f"Field B name wrong: {field_b_type['name']}"
    assert result['name'] == "container", f"Container name wrong: {result['name']}"
    print("✅ Test 4 passed: Multiple nested fields")

def test_case_5_list_of_nested():
    """Test list of nested objects."""
    result = ListContainer.avro_schema_to_python()

