#!/usr/bin/env python3
"""
Edge case tests for the nested metadata fix.
"""

from dataclasses_avroschema import AvroModel
from dataclasses import dataclass
import typing

# Edge case 1: Nested class with schema_name but parent without Meta
@dataclass
class NestedWithSchemaName(AvroModel):
    value: str
    class Meta:
        schema_name = "renamed_nested"

@dataclass
class ParentWithoutMeta(AvroModel):
    nested_field: NestedWithSchemaName
    # No Meta class

# Edge case 2: Both have schema_name  
@dataclass
class AnotherNested(AvroModel):
    value: int
    class Meta:
        schema_name = "another_renamed"

@dataclass
class ParentWithMeta(AvroModel):
    nested_field: AnotherNested
    class Meta:
        schema_name = "parent_renamed"

# Edge case 3: Optional nested field
@dataclass
class OptionalNested(AvroModel):
    value: str
    class Meta:
        schema_name = "optional_renamed"

@dataclass
class ContainerWithOptional(AvroModel):
    maybe_nested: typing.Optional[OptionalNested]
    class Meta:
        schema_name = "container_opt"

def test_edge_cases():
    """Test edge cases."""

    # Test 1: Parent without Meta
    result1 = ParentWithoutMeta.avro_schema_to_python()
    nested_name1 = result1['fields'][0]['type']['name']
    assert nested_name1 == "renamed_nested", f"Expected 'renamed_nested', got '{nested_name1}'"
    print("✅ Edge case 1 passed: Parent without Meta respects nested schema_name")

    # Test 2: Both with Meta
    result2 = ParentWithMeta.avro_schema_to_python()
    assert result2['name'] == "parent_renamed", f"Parent name wrong: {result2['name']}"
    nested_name2 = result2['fields'][0]['type']['name']
    assert nested_name2 == "another_renamed", f"Expected 'another_renamed', got '{nested_name2}'"
    print("✅ Edge case 2 passed: Both parent and nested respect their schema_names")

    # Test 3: Optional nested field
    result3 = ContainerWithOptional.avro_schema_to_python()
    field_type = result3['fields'][0]['type']
    # Should be a union [null, record]
    assert isinstance(field_type, list), "Optional field should create union"
    assert field_type[0] == "null", "First union element should be null"
    nested_record = field_type[1]
    assert nested_record['name'] == "optional_renamed", f"Expected 'optional_renamed', got '{nested_record['name']}'"
    print("✅ Edge case 3 passed: Optional nested field respects schema_name")

    print("\n🎉 All edge case tests passed!")

if __name__ == "__main__":
    test_edge_cases()

