#!/usr/bin/env python3
"""
Comprehensive test script for the Or/And dict wrapping fix
"""

import schema as s

def test_or_with_raw_dict():
    """Test Or with raw dict - original issue"""
    print("Testing Or with raw dict...")

    schema = s.Or(str, {
        s.Optional("gpu"): str,
        s.Optional("cpu"): str
    }, error="Got '{}'")

    result = schema.validate({"cpu": "face", "gpu": "cake"})
    assert result == {"cpu": "face", "gpu": "cake"}
    print("✓ SUCCESS")

def test_and_with_raw_dict():
    """Test And with raw dict"""
    print("Testing And with raw dict...")

    # This should work - data must satisfy both conditions
    schema = s.And({
        "name": str,
        "age": int
    }, {
        "name": lambda x: len(x) > 0,
        "age": lambda x: x > 0
    }, error="Got '{}'")

    result = schema.validate({"name": "John", "age": 25})
    assert result == {"name": "John", "age": 25}
    print("✓ SUCCESS")

def test_or_with_raw_list():
    """Test Or with raw list"""
    print("Testing Or with raw list...")

    schema = s.Or(str, [int, str], error="Got '{}'")
    result = schema.validate([1, "hello"])
    assert result == [1, "hello"]
    print("✓ SUCCESS")

def test_or_with_raw_tuple():
    """Test Or with raw tuple"""
    print("Testing Or with raw tuple...")

    schema = s.Or(str, (int, str, float), error="Got '{}'")
    result = schema.validate((42, "test", 3.14))
    assert result == (42, "test", 3.14)
    print("✓ SUCCESS")

def test_nested_or():
    """Test nested Or constructs"""
    print("Testing nested Or...")

    schema = s.Or(str, {
        "config": s.Or({
            "debug": bool
        }, {
            "release": bool
        })
    }, error="Got '{}'")

    result = schema.validate({"config": {"debug": True}})
    assert result == {"config": {"debug": True}}
    print("✓ SUCCESS")

def test_mixed_types():
    """Test mixing different raw types"""
    print("Testing mixed raw types...")

    schema = s.Or(str, {
        "items": [str]
    }, [int], error="Got '{}'")

    # Test dict path
    result1 = schema.validate({"items": ["a", "b"]})
    assert result1 == {"items": ["a", "b"]}

    # Test list path
    result2 = schema.validate([1, 2, 3])
    assert result2 == [1, 2, 3]

    print("✓ SUCCESS")

def test_backwards_compatibility():
    """Test that explicit Schema wrapping still works"""
    print("Testing backwards compatibility...")

    schema = s.Or(str, s.Schema({
        s.Optional("gpu"): str,
        s.Optional("cpu"): str
    }), error="Got '{}'")

    result = schema.validate({"cpu": "face", "gpu": "cake"})
    assert result == {"cpu": "face", "gpu": "cake"}
    print("✓ SUCCESS")

def test_repr_output():
    """Test that repr output is reasonable"""
    print("Testing repr output...")

    schema = s.Or(str, {"key": str})
    repr_str = repr(schema)
    print(f"Repr: {repr_str}")
    # Should show the wrapped Schema object
    assert "Schema({" in repr_str
    print("✓ SUCCESS")

def test_error_message_preservation():
    """Test that custom error messages still work"""
    print("Testing error message preservation...")

    schema = s.Or(str, {"key": str}, error="Custom error for {}")

    try:
        schema.validate(123)  # Neither str nor dict
        assert False, "Should have raised SchemaError"
    except s.SchemaError as e:
        error_msg = str(e)
        print(f"Error message: {error_msg}")
        # Should contain our custom error
        assert "Custom error for" in error_msg
    print("✓ SUCCESS")

if __name__ == "__main__":
    test_or_with_raw_dict()
    test_and_with_raw_dict()
    test_or_with_raw_list()
    test_or_with_raw_tuple()
    test_nested_or()
    test_mixed_types()
    test_backwards_compatibility()
    test_repr_output()
    test_error_message_preservation()
    print("\n🎉 All tests passed!")

