    log = logging.getLogger(__name__)
    if not os.path.exists(BINTRAY_CREDENTIAL_FILE_PATH):
        if raise_error:
            raise BintrayCredentialsNotFoundError(BINTRAY_CREDENTIAL_FILE_PATH)
        else:
            return None, None, None
    else:
        with open(BINTRAY_CREDENTIAL_FILE_PATH, 'r') as cred_file:
            lines = [line.replace('\n', '') for line in cred_file.readlines()]

            # Parse credentials into logical sections
            sections = []
            current_section = {}

            for line in lines:
                match = BINTRAY_PROPERTIES_RE.match(line)
                if match is not None:
                    try:
                        key, value = match.group(1, 2)
                        # If we encounter a realm and we already have a complete section,
                        # save the current section and start a new one
                        if key == 'realm' and 'user' in current_section and 'password' in current_section:
                            if current_section:  # Save the completed section
                                sections.append(current_section)
                            current_section = {}

                        current_section[key] = value
                    except IndexError:
                        pass

            # Add the last section if it has user and password
            if current_section and 'user' in current_section and 'password' in current_section:
                sections.append(current_section)

            # If we have sections, look for the appropriate one
            if sections:
                # Look for section with host=dl.bintray.com first (for downloads)
                for section in sections:
