"""Comprehensive test for the ContextChain defaults fix."""

import pint

def test_original_issue():
    """Test the exact scenario from the bug report."""
    print("=== Testing Original Issue ===")
    ureg = pint.UnitRegistry()
    ureg.load_definitions(
        """
        @context c1
            [time]->[length] : value * 10 m/s
        @end
        @context c2
            ft = 0.3 m
        @end
        @context c3
            lb = 0.5 kg
        @end
        """.splitlines()
    )

    try:
        ureg.enable_contexts("c1")
        ureg.enable_contexts("c2")
        ureg.enable_contexts("c3")
        print("✓ Original issue fixed - all contexts enabled successfully")
        return True
    except Exception as e:
        print(f"✗ Original issue still present: {e}")
        return False

def test_empty_context_chain():
    """Test accessing defaults on completely empty ContextChain."""
    print("\n=== Testing Empty ContextChain ===")
    from pint.context import ContextChain
    chain = ContextChain()
    try:
        defaults = chain.defaults
        print(f"✓ Empty chain defaults: {defaults}")
        assert defaults == {}
        return True
    except Exception as e:
        print(f"✗ Error with empty chain: {e}")
        return False

def test_context_with_defaults():
    """Test context that has actual defaults."""
    print("\n=== Testing Context With Defaults ===")
    ureg = pint.UnitRegistry()
    ureg.load_definitions(
        """
        @context with_defaults
            [time]->[length] : value * 10 m/s
            @defaults
                factor = 5
            @end
        @end
        """.splitlines()
    )

    try:
        ureg.enable_contexts("with_defaults")
        defaults = ureg._active_ctx.defaults
        print(f"✓ Context with defaults: {defaults}")
        # Should contain the default values
        return True
    except Exception as e:
        print(f"✗ Error with context defaults: {e}")
        return False

def test_mixed_contexts():
    """Test various combinations of contexts."""
    print("\n=== Testing Mixed Contexts ===")
    ureg = pint.UnitRegistry()
    ureg.load_definitions(
        """
        @context transform_only
            [time]->[length] : value * 10 m/s
        @end
        @context redefine_only
            ft = 0.3 m
        @end
        @context both
            [mass]->[energy] : value * 9e16
            lb = 0.45 kg
        @end
        @context with_defaults
            [temperature]->[energy] : value * 1.38e-23
            @defaults
                temp = 300
            @end
        @end
        """.splitlines()
    )

    try:
        # Enable contexts in various orders
        ureg.enable_contexts("redefine_only")  # Empty relation_to_context
        defaults1 = ureg._active_ctx.defaults
        print(f"✓ Redefine-only context defaults: {defaults1}")

        ureg.enable_contexts("transform_only")  # Non-empty relation_to_context
        defaults2 = ureg._active_ctx.defaults
        print(f"✓ Transform-only context defaults: {defaults2}")

        ureg.enable_contexts("with_defaults")  # Context with actual defaults
        defaults3 = ureg._active_ctx.defaults
        print(f"✓ Context with defaults: {defaults3}")

        print("✓ Mixed contexts test passed")
        return True
    except Exception as e:
        print(f"✗ Error in mixed contexts test: {e}")
        import traceback
        traceback.print_exc()
        return False

def test_disable_contexts():
    """Test that disabling contexts works properly."""
    print("\n=== Testing Disable Contexts ===")
    ureg = pint.UnitRegistry()
    ureg.load_definitions(
        """
        @context c1
            [time]->[length] : value * 10 m/s
        @end
        @context c2
            ft = 0.3 m
        @end
        """.splitlines()
    )

    try:
        ureg.enable_contexts("c1")
        ureg.enable_contexts("c2")

        # Check defaults before disabling
        defaults_before = ureg._active_ctx.defaults
        print(f"✓ Defaults before disable: {defaults_before}")

        # Disable last context
        ureg.disable_contexts(1)
        defaults_after = ureg._active_ctx.defaults
        print(f"✓ Defaults after disable: {defaults_after}")

        print("✓ Disable contexts test passed")
        return True
    except Exception as e:
        print(f"✗ Error in disable contexts test: {e}")
        return False

def run_all_tests():
    """Run all tests and report results."""
    tests = [
        test_empty_context_chain,
        test_original_issue,
        test_context_with_defaults,
        test_mixed_contexts,
        test_disable_contexts,
    ]

    results = []
    for test in tests:
        try:
            result = test()
            results.append(result)
        except Exception as e:
            print(f"✗ Test {test.__name__} failed with exception: {e}")
            results.append(False)

    passed = sum(results)
    total = len(results)
    print(f"\n=== SUMMARY ===")
    print(f"Passed: {passed}/{total} tests")

    if passed == total:
        print("🎉 All tests passed!")
        return True
    else:
        print("❌ Some tests failed")
        return False

if __name__ == "__main__":
    success = run_all_tests()
    exit(0 if success else 1)

